func agreementDocumentTablePhysical(body string, check *agreementNativeCheckSource, tree *agreementNativeProseAddressTree, target string) ([]agreementZeroActiveDiagnosticOwner, bool) {
	physical, _ := agreementProseP1Physical(body, check, tree, target)
	if !tree.Valid {
		return physical, false
	}
	seen := map[int]bool{}
	for i := range physical {
		seen[physical[i].Field] = true
	}
	for fi, f := range check.Fields {
		if seen[fi] || f.Comment || f.Escaped || len(f.Targets) != 1 || f.Targets[0] != target {
			continue
		}
		matches := 0
		var selected agreementUnusedParagraphDiagnosticOwner
		for ri, nodes := range tree.Trees {
			if ri != 0 || len(nodes) == 0 || nodes[0].Kind != "Document" {
				continue
			}
			for ni, n := range nodes {
				if n.Kind != "TableCell" {
					continue
				}
				for li, line := range n.Lines {
					if line.Start <= f.Span.Start && f.Span.Stop <= line.Stop {
						matches++
						selected = agreementUnusedParagraphDiagnosticOwner{Field: fi, Definition: -1, Root: ri, Node: ni, Line: li}
					}
				}
			}
		}
		if matches == 1 {
			physical = append(physical, agreementZeroActiveDiagnosticOwner{Field: fi, Family: "document-table-cell", Paragraph: selected})
		}
	}
	slices.SortFunc(physical, func(a, b agreementZeroActiveDiagnosticOwner) int { return a.Field - b.Field })
	return physical, len(physical) > 0
}
func agreementDocumentTablePrivateSingle(body, target string, o *agreementZeroActiveDiagnosticOwner, check *agreementNativeCheckSource) (string, []agreementMixedRename, bool) {
	if o.Family != "native-prose-line" && o.Family != "document-table-cell" {
		return agreementZeroActiveDiagnosticPrivate(body, target, []agreementZeroActiveDiagnosticOwner{*o}, check)
	}
	if o.Field < 0 || o.Field >= len(check.Fields) || target == "" || strings.Contains(body, "q") {
		return "", nil, false
	}
	tree := agreementNativeProseAddressTreeReading(body, nil)
	physical, valid := agreementDocumentTablePhysical(body, check, &tree, target)
	if !valid || !slices.Contains(physical, *o) {
		return "", nil, false
	}
	f := check.Fields[o.Field]
	if f.Span.Start < 0 || f.Span.Stop > len(body) || f.Span.Stop <= f.Span.Start || body[f.Span.Start:f.Span.Stop] != f.Word || !strings.HasPrefix(f.Word, "[[") || !strings.HasSuffix(f.Word, "]]") {
		return "", nil, false
	}
	inner := f.Word[2 : len(f.Word)-2]
	link, ok := graph.ParseWikilink(strings.ReplaceAll(inner, "\\|", "|"))
	if !ok || link.Target != target || strings.ContainsAny(inner, "[]\r\n") || strings.ContainsRune(inner, 96) {
		return "", nil, false
	}
	start := f.Span.Start + 2 + strings.Index(inner, target)
	stop := start + len(target)
	if start < f.Span.Start+2 || stop > f.Span.Stop-2 || body[start:stop] != target {
		return "", nil, false
	}
	change := agreementMixedRename{Field: o.Field, Span: graph.Span{Start: start, Stop: stop}, Old: target, New: strings.Repeat("q", len(target))}
	b := []byte(body)
	copy(b[start:stop], change.New)
	return string(b), []agreementMixedRename{change}, true
}
func agreementDocumentTableP0Producers(t *testing.T, body, target, section string, native agreementNativeOwnerSource, check *agreementNativeCheckSource) agreementDiagnosticProducerReading {
	t.Helper()
	tree := agreementNativeProseAddressTreeReading(body, nil)
	physical, ok := agreementDocumentTablePhysical(body, check, &tree, target)
	if !ok {
		return agreementDiagnosticProducerReading{Physical: physical}
	}
	raw, page := agreementIsolatedPage(t, agreementCase{Body: body})
	parts, pok := agreementCodeWindowParts(raw.HTML)
	if !pok {
		return agreementDiagnosticProducerReading{Physical: physical}
	}
	owners := []agreementZeroActiveDiagnosticOwner{}
	changes := []agreementMixedRename{}
	singles := []agreementZeroActiveDiagnosticSingle{}
	whole := []byte(body)
	expected := slices.Clone(raw.Diagnostics)
	used := map[int]bool{}
	for owneri := range physical {
		owner := physical[owneri]
		if owner.Field < 0 || owner.Field >= len(check.Fields) {
			continue
		}
		private, one, valid := agreementDocumentTablePrivateSingle(body, target, &owner, check)
		if !valid || len(one) != 1 {
			continue
		}
		pr, pp := agreementIsolatedPage(t, agreementCase{Body: private})
		part, good := agreementCodeWindowParts(pr.HTML)
		if !good || !cmp.Equal(native, agreementNativeOwnerReading(private)) || !cmp.Equal(tree, agreementNativeProseAddressTreeReading(private, nil)) || raw.HTML != pr.HTML || !cmp.Equal(page, pp) || !cmp.Equal(parts, part) || len(raw.Diagnostics) != len(pr.Diagnostics) {
			continue
		}
		index := -1
		valid = true
		for i := range raw.Diagnostics {
			if cmp.Equal(raw.Diagnostics[i], pr.Diagnostics[i]) {
				continue
			}
			if index >= 0 {
				valid = false
				break
			}
			index = i
		}
		if !valid {
			continue
		}
		if index < 0 {
			continue
		}
		if index >= 0 {
			a, b := raw.Diagnostics[index], pr.Diagnostics[index]
			if used[index] || a.Kind != render.DiagWikilinkBroken || a.Target != target || a.Section != section || b.Target != one[0].New || a.Kind != b.Kind || a.Section != b.Section || a.Block != b.Block || b.Message != strings.ReplaceAll(a.Message, strconv.Quote(target), strconv.Quote(one[0].New)) {
				continue
			}
			used[index] = true
			expected[index] = b
		}
		owners = append(owners, owner)
		changes = append(changes, one[0])
		copy(whole[one[0].Span.Start:one[0].Span.Stop], one[0].New)
		singles = append(singles, agreementZeroActiveDiagnosticSingle{Field: owner.Field, Index: index, Start: one[0].Span.Start, Body: private, Diagnostics: pr.Diagnostics})
	}
	return agreementDiagnosticProducerReading{Physical: physical, Owners: owners, Changes: changes, Private: string(whole), Diagnostics: expected, Singles: singles, Valid: len(owners) > 0}
}

