func agreementDocumentTableDifference(c agreementCase, f *agreementFailure, raw string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 || (f.Property != "P0" && f.Property != "P1") || (f.Property == "P0" && (f.Identity != "diagnostic-html" || f.Direction != "diagnostic-only")) || (f.Property == "P1" && (f.Identity != "citation-occurrences" || f.Direction != "judge-only")) || f.Multiplicity < 1 || f.Tuple.SourceRole != "" || (f.Property == "P0" && f.Tuple.State != "wikilink-broken") || (f.Property == "P1" && f.Tuple.State != "") || f.Fragment != "" || f.Cut != "" || f.PagePresent || f.JudgeAccepted || f.ExcerptFound {
		return "", "", ""
	}
	records := agreementDocumentTableDeclarations()
	for i := range records {
		r := &records[i]
		if r.Body != c.Body || r.Target != f.Tuple.Target || r.Section != f.Tuple.Section || r.Property != f.Property {
			continue
		}
		native := agreementNativeOwnerReading(c.Body)
		check := agreementNativeCheckReading(c.Body, native)
		tree := agreementNativeProseAddressTreeReading(c.Body, nil)
		parts, ok := agreementCodeWindowParts(raw)
		physical, pok := agreementDocumentTablePhysical(c.Body, &check, &tree, r.Target)
		private, changes, valid := agreementDocumentTablePrivate(c.Body, r.Target, r.Owners, &check)
		if agreementSignature(f) != r.Selected || !ok || !pok || !valid || private != r.Private || !cmp.Equal(changes, r.Changes) || !cmp.Equal(physical, r.Physical) || !cmp.Equal(native, r.Native) || !cmp.Equal(check, r.Check) || !cmp.Equal(tree, r.Tree) || !cmp.Equal(parts, r.Parts) || raw != r.HTML || !cmp.Equal(*page, r.Page) || !cmp.Equal(diagnostics, r.Diagnostics) || !cmp.Equal(agreementNativeCodePayloadSites(c.Body), r.Sites) || !cmp.Equal(agreementNativeHTMLAddressSites(c.Body), r.HTMLSites) || !cmp.Equal(agreementRemovedCommentDiagnosticRead(c.Body), r.Removed) || !cmp.Equal(agreementDocumentTableReading(c.Body), r.CheckRemoved) || !cmp.Equal(judge.LinkTargets(c.Body), r.Targets) || !maps.Equal(agreementMixedCurrent(failures), r.Signatures) || !agreementDocumentTableProjection(r, failures, r.After, r.PrivateDiagnostics) {
			return "", "", ""
		}
		if r.Property == "P1" {
			return "debt", "#1011 stage 5", "judge"
		}
		return "debt", "#1011 stage 5", "page-diagnostic"
	}
	return "", "", ""
}

func agreementDocumentTableFailures(t *testing.T, body string) (render.Result, agreementHTML, []agreementFailure) {
	t.Helper()
	raw, page := agreementIsolatedPage(t, agreementCase{Body: body})
	failures := agreementPageFailures(body, &raw, &page)
	failures = append(failures, agreementFragmentFailures(t, []agreementCase{{Body: body}}, []agreementHTML{page})[0]...)
	return raw, page, failures
}

