func agreementDocumentTableProjection(r *agreementDocumentTableDeclaration, before, after []agreementFailure, diagnostics []render.Diagnostic) bool {
	if r == nil {
		return false
	}
	if r.Property == "P0" {
		return agreementDocumentTableP0Projection(r, before, after, diagnostics)
	}
	if r.Property == "P1" {
		return agreementDocumentTableP1Projection(r, before, after, diagnostics)
	}
	return false
}
func agreementDocumentTableProducers(t *testing.T, body, target, section, property string, native agreementNativeOwnerSource, check *agreementNativeCheckSource) agreementDiagnosticProducerReading {
	t.Helper()
	if property == "P0" {
		return agreementDocumentTableP0Producers(t, body, target, section, native, check)
	}
	if property == "P1" {
		return agreementDocumentTableP1Producers(t, body, target, native, check)
	}
	return agreementDiagnosticProducerReading{}
}
func agreementDocumentTablePrivate(body, target string, owners []agreementZeroActiveDiagnosticOwner, check *agreementNativeCheckSource) (string, []agreementMixedRename, bool) {
	tree := agreementNativeProseAddressTreeReading(body, nil)
	physical, ok := agreementDocumentTablePhysical(body, check, &tree, target)
	if !ok || len(owners) == 0 {
		return "", nil, false
	}
	bodyBytes := []byte(body)
	changes := []agreementMixedRename{}
	seen := map[int]bool{}
	for oi := range owners {
		o := owners[oi]
		if seen[o.Field] || !slices.Contains(physical, o) {
			return "", nil, false
		}
		seen[o.Field] = true
		_, one, valid := agreementDocumentTablePrivateSingle(body, target, &o, check)
		if !valid || len(one) != 1 {
			return "", nil, false
		}
		c := one[0]
		copy(bodyBytes[c.Span.Start:c.Span.Stop], c.New)
		changes = append(changes, c)
	}
	return string(bodyBytes), changes, true
}
